CREATE DATABASE IF NOT EXISTS hr_system CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
USE hr_system;
SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS leave_requests, users, employees, departments;
SET FOREIGN_KEY_CHECKS=1;
CREATE TABLE departments (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(60) NOT NULL UNIQUE) ENGINE=InnoDB;
CREATE TABLE employees (
 id INT AUTO_INCREMENT PRIMARY KEY, emp_code VARCHAR(20) NOT NULL UNIQUE, full_name VARCHAR(100) NOT NULL,
 gender ENUM('Male','Female') NOT NULL, age TINYINT UNSIGNED NOT NULL, email VARCHAR(120) NOT NULL,
 department_id INT NOT NULL, job_role VARCHAR(80) NOT NULL, hire_date DATE NOT NULL,
 monthly_income INT NOT NULL, years_at_company TINYINT UNSIGNED NOT NULL,
 overtime ENUM('Yes','No') NOT NULL, job_satisfaction TINYINT NOT NULL, work_life_balance TINYINT NOT NULL,
 performance_rating TINYINT NOT NULL, distance_from_home SMALLINT NOT NULL, absent_days SMALLINT NOT NULL,
 training_hours SMALLINT NOT NULL, attrition ENUM('Yes','No') NOT NULL DEFAULT 'No',
 FOREIGN KEY (department_id) REFERENCES departments(id), KEY idx_attrition (attrition)) ENGINE=InnoDB;
CREATE TABLE users (id INT AUTO_INCREMENT PRIMARY KEY, username VARCHAR(40) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL,
 role ENUM('admin','hr','employee') NOT NULL, employee_id INT NULL,
 FOREIGN KEY (employee_id) REFERENCES employees(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE leave_requests (id INT AUTO_INCREMENT PRIMARY KEY, employee_id INT NOT NULL,
 leave_type ENUM('Annual','Casual','Sick') NOT NULL, start_date DATE NOT NULL, end_date DATE NOT NULL, days SMALLINT NOT NULL,
 reason VARCHAR(200) NOT NULL DEFAULT '', status ENUM('Pending','Approved','Rejected') NOT NULL DEFAULT 'Pending',
 created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
 FOREIGN KEY (employee_id) REFERENCES employees(id) ON DELETE CASCADE) ENGINE=InnoDB;
